func (this *Control) wM_NCHITTEST_(wParam int64, lParam int64) *win32.LRESULT {
	if !win32.OSIsWindowEnabled(this.Handle) {
		return nil
	}
	if !this.IsActive() {
		return win32.NewLRESULT(int64(win32.OSHTTRANSPARENT))
	}
	return nil
}

